#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 63
#define MAX_VALUE 3999

static const char *const SYMS[] = {
    "M", "CM", "D", "CD", "C",
    "XC", "L", "XL", "X", "IX",
    "V", "IV", "I"
};
static const int VALS[] = {
    1000, 900, 500, 400, 100,
    90, 50, 40, 10, 9,
    5, 4, 1
};

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    const char *src = argv[1];
    size_t src_len = strlen(src);
    if (src_len == 0 || src_len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }
    char upper[MAX_INPUT_LEN + 1];
    for (size_t i = 0; i < src_len; ++i) {
        unsigned char c = (unsigned char)src[i];
        if (c >= 'a' && c <= 'z') c -= ('a' - 'A');
        upper[i] = (char)c;
    }
    upper[src_len] = '\0';
    char canonical[MAX_INPUT_LEN + 1];
    size_t can_pos = 0;
    int value = 0;
    size_t pos = 0;
    while (pos < src_len) {
        int matched = 0;
        for (size_t i = 0; i < sizeof(SYMS)/sizeof(SYMS[0]); ++i) {
            size_t sym_len = strlen(SYMS[i]);
            if (pos + sym_len <= src_len && strncmp(upper + pos, SYMS[i], sym_len) == 0) {
                value += VALS[i];
                memcpy(canonical + can_pos, SYMS[i], sym_len);
                can_pos += sym_len;
                pos += sym_len;
                matched = 1;
                break;
            }
        }
        if (!matched) {
            puts("INVALID");
            return 0;
        }
    }
    canonical[can_pos] = '\0';
    if (value > MAX_VALUE) {
        puts("INVALID");
        return 0;
    }
    if (strcmp(upper, canonical) != 0) {
        puts("INVALID");
        return 0;
    }
    printf("%d\n", value);
    return 0;
}
